import{_ as l,H as a,f as t,i}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"09 | 3KU法则：为一个订餐系统设计全栈测试方案","description":"","frontmatter":{},"headers":[{"level":3,"title":"下线通知","slug":"下线通知","link":"#下线通知","children":[]},{"level":2,"title":"FoodCome 的订餐需求","slug":"foodcome-的订餐需求","link":"#foodcome-的订餐需求","children":[{"level":3,"title":"下线通知","slug":"下线通知-1","link":"#下线通知-1","children":[]}]},{"level":2,"title":"做不做自动化测试？","slug":"做不做自动化测试","link":"#做不做自动化测试","children":[]}],"relativePath":"自动化测试高手课/09｜3KU法则：为一个订餐系统设计全栈测试方案.md","filePath":"自动化测试高手课/09｜3KU法则：为一个订餐系统设计全栈测试方案.md","lastUpdated":1795563698000}'),o={name:"自动化测试高手课/09｜3KU法则：为一个订餐系统设计全栈测试方案.md"};function r(n,e,s,p,_,d){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="_09-3ku法则-为一个订餐系统设计全栈测试方案" tabindex="-1">09 | 3KU法则：为一个订餐系统设计全栈测试方案 <a class="header-anchor" href="#_09-3ku法则-为一个订餐系统设计全栈测试方案" aria-label="Permalink to &quot;09 | 3KU法则：为一个订餐系统设计全栈测试方案&quot;">​</a></h1><ul><li>登录</li></ul><h3 id="下线通知" tabindex="-1">下线通知 <a class="header-anchor" href="#下线通知" aria-label="Permalink to &quot;下线通知&quot;">​</a></h3><ul><li><p>该账号已在其他同类设备登录，如非本人操作，则密码可能已经泄露，建议立即更换密码</p></li><li><p>确定</p></li></ul><p>你好，我是柳胜。</p><p>上一讲，我们找出了 FoodCome 订餐系统各截面的测试需求，今天我们就根据这些需求，完成测试设计，给这个订餐系统设计一个全栈的测试方案。我们前面讲到的很多思路和原则，都能在今天的课程里得以应用。</p><p>这个测试方案非常关键，它能回答自动化测试设计中的四大基本问题：做不做自动化？在哪里做、怎么做、怎么运行。这四个基本问题梳理清楚了，自动化测试项目就相当于有了骨架。</p><h2 id="foodcome-的订餐需求" tabindex="-1">FoodCome 的订餐需求 <a class="header-anchor" href="#foodcome-的订餐需求" aria-label="Permalink to &quot;FoodCome 的订餐需求&quot;">​</a></h2><p>我们先列出前几讲提炼的测试需求，每项需求都过一遍上面的问题清单。让我们头脑中的测试方案，形成一个文档化的列表。</p><p>结合 FoodCome 订餐系统的例子，我们把测试需求整理如下：</p><ul><li>登录</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/09/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%AB%98%E6%89%8B%E8%AF%BE/images/09/1.png" alt=""></a></p><ul><li>测试需求表1.0</li></ul><p>订餐系统还有很多其他的测试需求，比如兼容性、安全性等等，因为本专栏的关注点是自动化测试，我在这里就不再列出来了。</p><h3 id="下线通知-1" tabindex="-1">下线通知 <a class="header-anchor" href="#下线通知-1" aria-label="Permalink to &quot;下线通知&quot;">​</a></h3><h2 id="做不做自动化测试" tabindex="-1">做不做自动化测试？ <a class="header-anchor" href="#做不做自动化测试" aria-label="Permalink to &quot;做不做自动化测试？&quot;">​</a></h2><ul><li>该账号已在其他同类设备登录，如非本人操作，则密码可能已经泄露，建议立即更</li></ul><p>有了文档化的测试需求列表后，我们在设计自动化测试方案时，需要先想清楚，这些需求做不</p><ul><li>换密码</li></ul><p>做自动化测试？</p><ul><li>确定</li></ul><p>测试四象限法则能帮我们有效完成这个思考过程。这个测试四象限，是布雷·麦瑞克提出来的方法模型：根据需求的性质和等级 2 个维度，对测试需求进行分类。</p><p>一个维度是测试需求的性质，是技术性还是业务性的？通俗来说就是，如果这个需求越靠近程序员的思维，比如算法、接口、事务等等，它的技术性就越强；而越靠近用户的思维，比如工作流，场景等等，就是业务性越强。</p><p>该试读文章来自《自动化测试高手课》，如需阅读全部文章，请购买文章所属专栏，新人首单¥59</p>',24)])])}const c=l(o,[["render",r]]);export{h as __pageData,c as default};
